let S={v:3,lang:'es',view:'home',activeList:'quick',activeProject:'solar',activeItem:null,projectTab:'overview',filter:'all',priorityScope:'need',lists:[],projects:[],items:[],suppliers:[],settings:{usdToMxn:FX.rate,fxDate:FX.date,fxSource:FX.source,sync:'local'},meta:{onboarded:false,updatedAt:null}};
