function baseItem(o={}){return{id:o.id||`i${Date.now()}${Math.random().toString(36).slice(2,6)}`,ct:o.ct||'list',cid:o.cid||'quick',priority:o.priority||'need',es:o.es||'',en:o.en||o.es||'',qty:o.qty||1,est:Number(o.est||0),cur:o.cur||'MXN',brand:o.brand||'',des:o.des||'',den:o.den||'',wes:o.wes||'',wen:o.wen||'',done:!!o.done,owned:!!o.owned,status:o.status||'researching',urgency:o.urgency||(o.priority==='need'?'this-week':'later'),assigned:o.assigned||'shared',budgetCap:Number(o.budgetCap||0),budgetCur:o.budgetCur||'MXN',targetDate:o.targetDate||'',offers:Array.isArray(o.offers)?o.offers:[],paid:Number(o.paid||0),paidCur:o.paidCur||'MXN',shipping:Number(o.shipping||0),tax:Number(o.tax||0),import:Number(o.import||0),discount:Number(o.discount||0),refund:Number(o.refund||0),seller:o.seller||'',notes:o.notes||'',photo:o.photo||'',receipt:o.receipt||'',warranty:o.warranty||'',serial:o.serial||'',returnBy:o.returnBy||''}}
function seed(){if(!Array.isArray(S.lists)||!S.lists.length)S.lists=[{id:'quick',es:'Lista rápida',en:'Quick list',cat:'home'},{id:'travel',es:'Viajes',en:'Travel',cat:'travel'},{id:'personal',es:'Personal',en:'Personal',cat:'personal'}];if(!Array.isArray(S.projects)||!S.projects.length)S.projects=[{id:'solar',es:'Respaldo solar Starlink',en:'Starlink solar backup',des:'Primer proyecto real de Chispa. La lista solar vive aquí, separada de tus compras cotidianas.',den:'Chispa’s first real project. The solar checklist lives here, separate from everyday shopping.'}];S.items=(S.items||[]).map(x=>baseItem(x));if(!S.items.some(x=>x.ct==='project'&&x.cid==='solar'))S.items.push(...solarSeed.map(x=>baseItem({id:x[0],ct:'project',cid:'solar',priority:x[1],es:x[2],en:x[3],qty:x[4],est:x[5],cur:'USD',brand:x[6],des:x[7],den:x[8],wes:x[9],wen:x[10],done:!!x[11],owned:!!x[11],status:x[11]?'owned':'researching'})));if(!Array.isArray(S.suppliers)||!S.suppliers.length||S.suppliers.some(x=>!x.type))S.suppliers=structuredClone(supplierSeed);S.v=3}
function migrate(o){if(o&&typeof o==='object')S={...S,...o,settings:{...S.settings,...(o.settings||{})},meta:{...S.meta,...(o.meta||{})}};S.items=(S.items||[]).map(x=>x.nameEs&&!x.es?baseItem({...x,ct:x.ct||'project',cid:x.cid||x.project||'solar',es:x.nameEs,en:x.nameEn||x.nameEs,des:x.descEs||'',den:x.descEn||'',wes:x.warnEs||'',wen:x.warnEn||'',est:Number(x.estUsd||0),cur:'USD',paid:Number(x.paidMxn||0),paidCur:'MXN'}):baseItem(x));if(!S.settings.fxDate)S.settings={...S.settings,usdToMxn:FX.rate,fxDate:FX.date,fxSource:FX.source};seed()}
function openDB(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
async function load(){try{const d=await openDB(),r=d.transaction(STORE,'readonly').objectStore(STORE).get('app');r.onsuccess=()=>{migrate(r.result);applyRoute();sharedHash();render()};r.onerror=()=>{seed();applyRoute();render()}}catch{seed();applyRoute();render()}}
async function save(){S.meta.updatedAt=new Date().toISOString();try{(await openDB()).transaction(STORE,'readwrite').objectStore(STORE).put(S,'app')}catch{}}
const money=(v,c='MXN')=>new Intl.NumberFormat(S.lang==='es'?'es-MX':'en-US',{style:'currency',currency:c,maximumFractionDigits:c==='MXN'?0:2}).format(Number(v||0));const toMxn=(v,c='MXN')=>c==='USD'?Number(v||0)*Number(S.settings.usdToMxn||FX.rate):Number(v||0),toUsd=v=>Number(v||0)/Number(S.settings.usdToMxn||FX.rate),dual=v=>`${money(v,'MXN')} · ${money(toUsd(v),'USD')}`,estimate=i=>toMxn(i.est,i.cur),spent=i=>i.status==='returned'?0:Math.max(0,toMxn(Number(i.paid||0)+Number(i.shipping||0)+Number(i.tax||0)+Number(i.import||0)-Number(i.discount||0),i.paidCur||'MXN')-Number(i.refund||0)),landed=o=>toMxn(Number(o.price||0)+Number(o.shipping||0)+Number(o.tax||0)+Number(o.import||0)-Number(o.discount||0),o.cur||'MXN');
const items=(ct,cid)=>S.items.filter(x=>x.ct===ct&&x.cid===cid),filtered=(ct,cid)=>items(ct,cid).filter(x=>S.filter==='all'||x.priority===S.filter),listName=l=>S.lang==='es'?l.es:l.en,projectName=p=>S.lang==='es'?p.es:p.en,categoryName=id=>{const c=categories.find(x=>x[0]===id);return c?t(c[1],c[2]):id};function totals(a){return{n:a.length,done:a.filter(x=>x.done||x.owned).length,est:a.reduce((s,x)=>s+estimate(x),0),spent:a.reduce((s,x)=>s+spent(x),0)}}
function searchUrl(id,q){const e=encodeURIComponent(q);return id==='amzmx'?`https://www.amazon.com.mx/s?k=${e}`:id==='amzus'?`https://www.amazon.com/s?k=${e}`:id==='ml'?`https://listado.mercadolibre.com.mx/${e}`:id==='temu'?`https://www.temu.com/search_result.html?search_key=${e}`:`https://www.google.com/search?q=${e}`}
function applyRoute(){const u=new URL(location.href),v=u.searchParams.get('view'),action=u.searchParams.get('action');if(v==='projects')S.view='projects';if(action==='add')setTimeout(()=>sheet('choice'),50)}
function header(){return `<header class="top"><button class="brand" data-go="home"><span>${I('spark')}</span>CHISPA</button><div><button class="plain" id="lang">${S.lang==='es'?'EN':'ES'}</button><button class="circle" id="add" aria-label="${t('Agregar','Add')}">${I('plus')}</button></div></header>`}
function hero(){return `<section class="hero"><div class="hero-copy"><span class="kick">CHISPA</span><h1>${t('Compra lo que necesitas. Recuerda lo que importa.','Buy what you need. Remember what matters.')}</h1><p>${t('Tu espacio bilingüe para listas, proyectos y viajes. Compara ofertas guardadas, controla gastos y sigue funcionando sin internet.','Your bilingual space for lists, projects and travel. Compare saved offers, track spending and keep working offline.')}</p><div class="actions"><button class="primary" data-start>${t('Empezar mi lista','Start my list')}</button><button class="secondary" data-project="solar">${t('Ver proyecto solar','View solar project')}</button></div></div><div class="hero-photo"><img src="/chispa-hero.webp" alt="${t('Mujer frente al mar escribiendo una lista en una tableta','Woman by the sea writing a list on a tablet')}" onerror="this.remove();this.parentElement.classList.add('fallback')"><div class="fallback-ui"><div><small>${t('Necesario','Need to have')}</small><b>6</b></div><div><small>${t('Bueno tener','Nice to have')}</small><b>4</b></div><i></i><i></i></div></div></section>`}
function quick(){return `<section class="quick"><label>${t('¿Qué necesitamos?','What do we need?')}</label><div><input id="quick" placeholder="${t('Escribe algo para agregar…','Type something to add…')}"><button class="primary icon" id="quickBtn" aria-label="${t('Agregar a lista rápida','Add to quick list')}">${I('plus')}</button></div></section>`}
function urgencyLabel(v){return v==='today'?t('Hoy','Today'):v==='this-week'?t('Esta semana','This week'):t('Después','Later')}function assignedLabel(v){return v==='me'?t('Yo','Me'):v==='wife'?t('Esposa','Wife'):t('Compartido','Shared')}
function line(i){const n=S.lang==='es'?i.es:i.en,b=i.offers?.length?Math.min(...i.offers.map(landed)):i.est?estimate(i):0;return `<button class="item" data-item="${i.id}"><span class="box ${i.done?'done':''}">${i.done?I('check'):''}</span><span><strong>${esc(n)}</strong><small>${i.priority==='need'?t('Necesario','Need to have'):t('Bueno tener','Nice to have')} · ${urgencyLabel(i.urgency)}</small></span>${b?`<em>${dual(b)}</em>`:''}${I('next')}</button>`}
function home(){const everyday=S.items.filter(x=>x.ct==='list'),need=everyday.filter(x=>x.priority==='need'&&!x.done).length,nice=everyday.filter(x=>x.priority==='nice'&&!x.done).length,p=S.projects.find(x=>x.id==='solar'),tt=totals(items('project','solar'));return `<main>${!S.meta.onboarded?hero():''}<div class="page">${quick()}<div class="priority-cards"><button data-priority-view="need"><span>${t('Necesario','Need to have')}</span><b>${need}</b></button><button data-priority-view="nice"><span>${t('Bueno tener','Nice to have')}</span><b>${nice}</b></button></div><div class="section-head"><div><span class="kick">${t('Proyectos activos','Active projects')}</span><h2>${t('En progreso','In progress')}</h2></div><button class="link" data-go="projects">${t('Ver todos','See all')}</button></div><button class="feature-project" data-project="solar"><div><small>${t('ENERGÍA · PROYECTO','ENERGY · PROJECT')}</small><h3>${esc(projectName(p))}</h3><p>${tt.done}/${tt.n} ${t('artículos listos','items done')}</p></div><b>${tt.n?Math.round(tt.done/tt.n*100):0}%</b></button></div></main>`}
function priorityView(){const a=S.items.filter(x=>x.ct==='list'&&x.priority===S.priorityScope&&!x.done);return `<main class="page"><button class="back" data-go="home">${I('back')} ${t('Inicio','Home')}</button><div class="page-head"><div><span class="kick">${t('Prioridad','Priority')}</span><h1>${S.priorityScope==='need'?t('Necesario','Need to have'):t('Bueno tener','Nice to have')}</h1><p>${t('Artículos de todas tus listas, reunidos por prioridad.','Items from all your everyday lists, gathered by priority.')}</p></div></div><div class="item-list">${a.length?a.map(line).join(''):`<div class="empty">${t('No hay artículos pendientes aquí.','No pending items here.')}</div>`}</div></main>`}
function lists(){return `<main class="page"><div class="page-head"><div><span class="kick">${t('Listas','Lists')}</span><h1>${t('Compras cotidianas','Everyday shopping')}</h1><p>${t('Las prioridades viven dentro de cada lista. Los proyectos tienen su propio espacio.','Priorities live inside each list. Projects have their own space.')}</p></div><button class="primary" data-new-list>${I('plus')} ${t('Nueva lista','New list')}</button></div><div class="chips">${categories.map(c=>`<span>${esc(t(c[1],c[2]))}</span>`).join('')}</div><div class="cards">${S.lists.map(l=>{const tt=totals(items('list',l.id));return `<div class="card-wrap"><button class="card" data-list="${l.id}">${I('list')}<span><small>${esc(categoryName(l.cat))}</small><strong>${esc(listName(l))}</strong><em>${tt.n} ${t('artículos','items')} · ${tt.done} ${t('listos','done')}</em></span>${I('next')}</button><button class="mini-edit" data-edit-list="${l.id}" aria-label="${t('Editar lista','Edit list')}">${I('edit')}</button></div>`}).join('')}</div></main>`}
function filters(){return `<div class="filters"><button data-filter="all" class="${S.filter==='all'?'on':''}">${t('Todos','All')}</button><button data-filter="need" class="${S.filter==='need'?'on':''}">${t('Necesario','Need to have')}</button><button data-filter="nice" class="${S.filter==='nice'?'on':''}">${t('Bueno tener','Nice to have')}</button></div>`}
function listView(){const l=S.lists.find(x=>x.id===S.activeList)||S.lists[0],a=filtered('list',l.id),tt=totals(items('list',l.id));return `<main class="page"><button class="back" data-go="lists">${I('back')} ${t('Listas','Lists')}</button><div class="page-head"><div><span class="kick">${esc(categoryName(l.cat))}</span><h1>${esc(listName(l))}</h1><p>${tt.done}/${tt.n} ${t('listos','done')} · ${dual(tt.spent)} ${t('gastado','spent')}</p></div><div class="actions"><button class="secondary" data-edit-list="${l.id}">${I('edit')} ${t('Editar','Edit')}</button><button class="primary" data-add-item data-ct="list" data-cid="${l.id}">${I('plus')} ${t('Agregar','Add')}</button></div></div>${filters()}<div class="item-list">${a.length?a.map(line).join(''):`<div class="empty">${t('Nada aquí todavía. Agrega el primer artículo.','Nothing here yet. Add the first item.')}</div>`}</div></main>`}
function searchView(){return `<main class="page narrow"><div class="page-head"><div><span class="kick">${t('Buscar','Search')}</span><h1>${t('Busca una vez. Compara mejor.','Search once. Compare better.')}</h1><p>${t('Abre búsquedas en tus mercados principales. Guarda las ofertas que encuentres para comparar el costo total real.','Open searches across your main marketplaces. Save offers you find to compare true landed cost.')}</p></div></div><div class="search"><input id="q" placeholder="${t('¿Qué estás buscando?','What are you looking for?')}"><button class="primary" id="searchBtn">${I('search')} ${t('Buscar','Search')}</button></div><div id="marketLinks" class="markets">${markets.map(m=>`<div><strong>${m[1]}</strong><small>${t('Escribe arriba para buscar','Type above to search')}</small></div>`).join('')}</div><div class="note"><strong>${t('Comparación honesta','Honest comparison')}</strong><p>${t('Chispa no inventa precios. Guarda cada oferta con precio, envío, impuestos, importación, entrega y garantía; luego las ordena por costo total y convierte MXN/USD.','Chispa does not invent prices. Save each offer with price, shipping, tax, import, delivery and warranty; Chispa ranks landed total and converts MXN/USD.')}</p></div></main>`}
function projects(){return `<main class="page"><div class="page-head"><div><span class="kick">${t('Proyectos','Projects')}</span><h1>${t('Compras con un propósito','Shopping with a purpose')}</h1><p>${t('Cada proyecto tiene su propia lista, presupuesto, documentos y referencias.','Each project has its own checklist, budget, documents and references.')}</p></div><button class="primary" data-new-project>${I('plus')} ${t('Nuevo proyecto','New project')}</button></div><div class="project-grid">${S.projects.map(p=>{const tt=totals(items('project',p.id)),pct=tt.n?Math.round(tt.done/tt.n*100):0;return `<div class="project-wrap"><button class="project-card" data-project="${p.id}"><div><span>${I('folder')}</span><b>${pct}%</b></div><h2>${esc(projectName(p))}</h2><p>${esc(S.lang==='es'?(p.des||''):(p.den||''))}</p><footer><span><b>${tt.n}</b>${t('artículos','items')}</span><span><b>${tt.done}</b>${t('listos','done')}</span><span><b>${money(tt.spent)}</b>${t('gastado','spent')}</span></footer></button><button class="mini-edit" data-edit-project="${p.id}" aria-label="${t('Editar proyecto','Edit project')}">${I('edit')}</button></div>`}).join('')}</div></main>`}
function projectView(){const p=S.projects.find(x=>x.id===S.activeProject)||S.projects[0],a=items('project',p.id),tt=totals(a),pct=tt.n?Math.round(tt.done/tt.n*100):0,tabs=[['overview',t('Resumen','Overview')],['checklist',t('Lista','Checklist')],...(p.id==='solar'?[['wiring',t('Cableado','Wiring')],['suppliers',t('Proveedores','Suppliers')]]:[]),['docs',t('Documentos','Documents')]];let body=S.projectTab==='checklist'?`${filters()}<div class="project-tools"><button class="primary" data-add-item data-ct="project" data-cid="${p.id}">${I('plus')} ${t('Agregar artículo','Add item')}</button></div><div class="item-list">${filtered('project',p.id).map(line).join('')||`<div class="empty">${t('Nada aquí todavía.','Nothing here yet.')}</div>`}</div>`:S.projectTab==='wiring'?wiring():S.projectTab==='suppliers'?supplierCards(true):S.projectTab==='docs'?docs(p):`<div class="metrics"><div><span>${t('Progreso','Progress')}</span><b>${pct}%</b></div><div><span>${t('Estimación de presupuesto','Planning estimate')}</span><b>${dual(tt.est)}</b></div><div><span>${t('Gastado','Spent')}</span><b>${dual(tt.spent)}</b></div><div><span>${t('Por comprar','Remaining')}</span><b>${Math.max(0,tt.n-tt.done)}</b></div></div><div class="note"><strong>${t('Precios honestos','Honest pricing')}</strong><p>${t('Los importes iniciales son estimaciones de presupuesto, no precios de mercado verificados. Las ofertas guardadas muestran fuente, fecha y costo total.','Starter amounts are planning estimates, not verified market prices. Saved offers show source, date and landed total.')}</p></div>`;return `<main class="page"><button class="back" data-go="projects">${I('back')} ${t('Proyectos','Projects')}</button><div class="project-head"><div><span class="kick">${t('Proyecto','Project')}</span><h1>${esc(projectName(p))}</h1><p>${esc(S.lang==='es'?(p.des||''):(p.den||''))}</p><button class="link" data-edit-project="${p.id}">${t('Editar proyecto','Edit project')}</button></div><strong>${pct}%<small>${tt.done}/${tt.n} ${t('listos','done')}</small></strong></div><div class="tabs">${tabs.map(x=>`<button data-tab="${x[0]}" class="${S.projectTab===x[0]?'on':''}">${x[1]}</button>`).join('')}</div>${body}</main>`}
function wiring(){return `<div class="wiring">${[t('Paneles solares','Solar panels'),'Victron MPPT',t('Banco 24V LiFePO₄','24V LiFePO₄ bank'),t('Inversor seno puro 24V → 120V AC','24V pure-sine inverter → 120V AC'),'Starlink UTP-232L','Starlink'].map((x,i)=>`<div><b>${i+1}</b><strong>${x}</strong>${i<5?I('next'):''}</div>`).join('')}</div><div class="danger"><strong>${t('Seguridad','Safety')}</strong><p>${t('No conectes la batería de 24V directamente a la entrada Starlink de 57V. El fusible debe proteger el cable elegido y la instalación final debe revisarla un instalador solar/DC calificado.','Do not connect the 24V battery directly to the 57V Starlink input. Fuse sizing must protect the selected cable and final assembly should be checked by a qualified solar/DC installer.')}</p></div>`}
function docs(p){const a=items('project',p.id);return `<div class="doc-grid">${[[t('Fotos','Photos'),'photo'],[t('Recibos','Receipts'),'receipt'],[t('Garantías','Warranties'),'warranty'],[t('Series','Serials'),'serial']].map(x=>`<div><span>${x[0]}</span><b>${a.filter(i=>i[x[1]]).length}</b></div>`).join('')}</div><p class="muted">${t('Las referencias se guardan localmente. La carga de archivos y respaldo compartido se activan al conectar Supabase.','References are stored locally. File upload and shared backup activate when Supabase is connected.')}</p>`}
function supplierCards(projectOnly=false){return `<div class="supplier-grid">${S.suppliers.map(s=>`<article><span class="kick">${s.type==='local'?t('Local','Local'):t('En línea','Online')}</span><h3>${esc(s.name)}</h3>${s.es?`<p>${esc(t(s.es,s.en))}</p>`:''}<div class="links">${s.phone?`<a href="tel:${s.phone.replace(/\s/g,'')}">${t('Llamar','Call')} ${esc(s.phone)}</a>`:''}${s.email?`<a href="mailto:${esc(s.email)}">${t('Correo','Email')}</a>`:''}${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${t('Sitio','Website')} ↗</a>`:''}${s.type==='local'?`<a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent((s.name||'')+' '+(s.place||''))}" target="_blank" rel="noopener">Google Maps ↗</a><a href="https://maps.apple.com/?q=${encodeURIComponent((s.name||'')+' '+(s.place||''))}" target="_blank" rel="noopener">Apple Maps ↗</a><a href="https://www.waze.com/ul?q=${encodeURIComponent((s.name||'')+' '+(s.place||''))}&navigate=yes" target="_blank" rel="noopener">Waze ↗</a>`:''}</div>${projectOnly?'':`<div class="supplier-admin"><button data-edit-supplier="${s.id}" class="link">${t('Editar','Edit')}</button>${!['poderazul','amzmx','amzus','ml','temu'].includes(s.id)?`<button data-del-supplier="${s.id}" class="link danger-link">${t('Eliminar','Delete')}</button>`:''}</div>`}</article>`).join('')}</div>`}
function offerTotal(o){return landed(o)}
function itemView(){const i=S.items.find(x=>x.id===S.activeItem);if(!i)return home();const n=S.lang==='es'?i.es:i.en,a=S.lang==='es'?i.des:i.den,w=S.lang==='es'?i.wes:i.wen,os=(i.offers||[]).slice().sort((x,y)=>offerTotal(x)-offerTotal(y)),arr=filtered(i.ct,i.cid),ix=Math.max(0,arr.findIndex(x=>x.id===i.id)),prev=arr[(ix-1+arr.length)%arr.length],next=arr[(ix+1)%arr.length];return `<main class="page item-page"><button class="back" data-back-item>${I('back')} ${t('Volver','Back')}</button><div class="item-hero"><div class="photo">${i.photo?`<img src="${esc(i.photo)}" alt="${esc(n)}">`:`${I('spark')}<small>${t('Foto opcional','Optional photo')}</small>`}</div><div><span class="priority ${i.priority}">${i.priority==='need'?t('Necesario','Need to have'):t('Bueno tener','Nice to have')}</span><h1>${esc(n)}</h1><p>${esc(a||'')}</p><div class="price"><small>${os.length?t('Mejor oferta guardada','Best saved offer'):t('Estimación de presupuesto','Planning estimate')}</small><b>${dual(os.length?offerTotal(os[0]):estimate(i))}</b><em>${os.length?`${esc(os[0].seller||os[0].source||'')} · ${esc(os[0].date||'')}`:t('No es un precio de mercado verificado','Not a verified market price')}</em></div><label class="done"><input type="checkbox" data-done="${i.id}" ${i.done?'checked':''}> ${i.done?t('Comprado / listo','Bought / done'):t('Marcar como comprado','Mark as bought')}</label></div></div><div class="item-actions"><button class="primary" data-search-item>${I('search')} ${t('Buscar precios','Find prices')}</button><button class="secondary" data-add-offer>${t('Guardar oferta','Save offer')}</button></div>${os.length?`<section class="offers"><h2>${t('Ofertas guardadas','Saved offers')}</h2>${os.map((o,j)=>`<article class="offer ${j===0?'best':''}"><div><small>${j===0?t('Mejor costo total','Best landed cost'):esc(o.source)}</small><b>${dual(offerTotal(o))}</b><em>${esc(o.seller||'')} · ${esc(o.date||'')} ${o.delivery?`· ${esc(o.delivery)}`:''}</em></div><p>${t('Precio','Price')} ${money(o.price,o.cur)} · ${t('Envío','Shipping')} ${money(o.shipping,o.cur)} · ${t('Impuestos/importación','Tax/import')} ${money(Number(o.tax||0)+Number(o.import||0),o.cur)}</p>${o.warranty?`<p><strong>${t('Garantía/devolución','Warranty/returns')}:</strong> ${esc(o.warranty)}</p>`:''}${o.url?`<a href="${esc(o.url)}" target="_blank" rel="noopener">${t('Abrir oferta','Open offer')} ↗</a>`:''}<button data-del-offer="${o.id}" aria-label="${t('Eliminar oferta','Delete offer')}">${I('trash')}</button></article>`).join('')}</section>`:''}<details open><summary>${t('Detalles','Details')}</summary>${detailForm(i,w)}</details><details><summary>${t('Compra y gasto','Purchase & spending')}</summary>${purchaseForm(i)}</details><details><summary>${t('Recibo, garantía y serie','Receipt, warranty & serial')}</summary>${docForm(i)}</details><details><summary>${t('Notas','Notes')}</summary><textarea data-field="notes" data-id="${i.id}">${esc(i.notes||'')}</textarea></details>${arr.length>1?`<div class="pager"><button data-jump="${prev.id}">${I('back')}<span><small>${t('Anterior','Previous')}</small><b>${esc(S.lang==='es'?prev.es:prev.en)}</b></span></button><button data-jump="${next.id}"><span><small>${t('Siguiente','Next')}</small><b>${esc(S.lang==='es'?next.es:next.en)}</b></span>${I('next')}</button></div>`:''}</main>`}
function detailForm(i,w){return `<div class="detail-grid"><div><small>${t('Cantidad','Quantity')}</small><b>${esc(i.qty||1)}</b></div><div><small>${t('Marca recomendada','Recommended brand')}</small><b>${esc(i.brand||'—')}</b></div><div><small>${t('Urgencia','Urgency')}</small><b>${urgencyLabel(i.urgency)}</b></div><div><small>${t('Asignado a','Assigned to')}</small><b>${assignedLabel(i.assigned)}</b></div><div><small>${t('Fecha objetivo','Target date')}</small><b>${esc(i.targetDate||'—')}</b></div><div><small>${t('Tope de presupuesto','Budget cap')}</small><b>${i.budgetCap?money(i.budgetCap,i.budgetCur||'MXN'):'—'}</b></div>${w?`<div class="warning"><small>${t('Evita comprar por error','Avoid the wrong substitute')}</small><p>${esc(w)}</p></div>`:''}</div><div class="form compact-form"><label>${t('Urgencia','Urgency')}<select data-field="urgency" data-id="${i.id}"><option value="today" ${i.urgency==='today'?'selected':''}>${t('Hoy','Today')}</option><option value="this-week" ${i.urgency==='this-week'?'selected':''}>${t('Esta semana','This week')}</option><option value="later" ${i.urgency==='later'?'selected':''}>${t('Después','Later')}</option></select></label><label>${t('Asignado a','Assigned to')}<select data-field="assigned" data-id="${i.id}"><option value="shared" ${i.assigned==='shared'?'selected':''}>${t('Compartido','Shared')}</option><option value="me" ${i.assigned==='me'?'selected':''}>${t('Yo','Me')}</option><option value="wife" ${i.assigned==='wife'?'selected':''}>${t('Esposa','Wife')}</option></select></label><label>${t('Tope de presupuesto','Budget cap')}<input type="number" step=".01" data-field="budgetCap" data-id="${i.id}" value="${i.budgetCap||''}"></label><label>${t('Moneda','Currency')}<select data-field="budgetCur" data-id="${i.id}"><option ${i.budgetCur==='MXN'?'selected':''}>MXN</option><option ${i.budgetCur==='USD'?'selected':''}>USD</option></select></label><label>${t('Fecha objetivo','Target date')}<input type="date" data-field="targetDate" data-id="${i.id}" value="${i.targetDate||''}"></label><label>${t('Estado','Status')}<select data-field="status" data-id="${i.id}"><option value="researching" ${i.status==='researching'?'selected':''}>${t('Investigando','Researching')}</option><option value="quoted" ${i.status==='quoted'?'selected':''}>${t('Cotizado','Quoted')}</option><option value="ordered" ${i.status==='ordered'?'selected':''}>${t('Pedido','Ordered')}</option><option value="delivered" ${i.status==='delivered'?'selected':''}>${t('Entregado','Delivered')}</option><option value="returned" ${i.status==='returned'?'selected':''}>${t('Devuelto','Returned')}</option><option value="owned" ${i.status==='owned'?'selected':''}>${t('Ya tenemos','Already owned')}</option></select></label></div>`}
function purchaseForm(i){return `<div class="form"><label>${t('Precio pagado','Paid price')}<input type="number" step=".01" data-field="paid" data-id="${i.id}" value="${i.paid||''}"></label><label>${t('Moneda','Currency')}<select data-field="paidCur" data-id="${i.id}"><option ${i.paidCur==='MXN'?'selected':''}>MXN</option><option ${i.paidCur==='USD'?'selected':''}>USD</option></select></label><label>${t('Envío','Shipping')}<input type="number" step=".01" data-field="shipping" data-id="${i.id}" value="${i.shipping||''}"></label><label>${t('Impuestos','Tax')}<input type="number" step=".01" data-field="tax" data-id="${i.id}" value="${i.tax||''}"></label><label>${t('Importación','Import fees')}<input type="number" step=".01" data-field="import" data-id="${i.id}" value="${i.import||''}"></label><label>${t('Descuento','Discount')}<input type="number" step=".01" data-field="discount" data-id="${i.id}" value="${i.discount||''}"></label><label>${t('Reembolso','Refund')}<input type="number" step=".01" data-field="refund" data-id="${i.id}" value="${i.refund||''}"></label><label>${t('Vendedor','Seller')}<input data-field="seller" data-id="${i.id}" value="${esc(i.seller||'')}"></label><div class="total"><small>${t('Total registrado','Recorded total')}</small><b>${dual(spent(i))}</b></div></div>`}
function docForm(i){return `<div class="form"><label>${t('Foto del producto (URL)','Product photo (URL)')}<input data-field="photo" data-id="${i.id}" value="${esc(i.photo||'')}"></label><label>${t('Recibo (URL/referencia)','Receipt (URL/reference)')}<input data-field="receipt" data-id="${i.id}" value="${esc(i.receipt||'')}"></label><label>${t('Garantía (URL/referencia)','Warranty (URL/reference)')}<input data-field="warranty" data-id="${i.id}" value="${esc(i.warranty||'')}"></label><label>${t('Número de serie','Serial number')}<input data-field="serial" data-id="${i.id}" value="${esc(i.serial||'')}"></label><label>${t('Fecha límite de devolución','Return deadline')}<input type="date" data-field="returnBy" data-id="${i.id}" value="${i.returnBy||''}"></label></div>`}
function more(){return `<main class="page"><div class="page-head"><div><span class="kick">${t('Más','More')}</span><h1>${t('Chispa a tu manera','Your Chispa')}</h1></div></div><div class="menu"><button data-go="suppliers">${I('map')}<span><b>${t('Proveedores y ubicaciones','Suppliers & locations')}</b><small>${t('Tiendas locales y mercados en línea','Local stores and online marketplaces')}</small></span>${I('next')}</button><button data-go="settings">${I('gear')}<span><b>${t('Ajustes y respaldo','Settings & backup')}</b><small>${t('Moneda, memoria, compartir y exportar','Currency, memory, sharing and export')}</small></span>${I('next')}</button></div></main>`}
function supplierPage(){return `<main class="page"><button class="back" data-go="more">${I('back')} ${t('Más','More')}</button><div class="page-head"><div><span class="kick">${t('Proveedores','Suppliers')}</span><h1>${t('Dónde comprar','Where to buy')}</h1><p>${t('Las tiendas locales pueden tener teléfono y navegación. Los mercados en línea solo muestran enlaces de compra.','Local stores can include phone and navigation. Online marketplaces only show shopping links.')}</p></div><button class="primary" data-new-supplier>${I('plus')} ${t('Agregar proveedor','Add supplier')}</button></div>${supplierCards(false)}</main>`}
function settings(){return `<main class="page"><button class="back" data-go="more">${I('back')} ${t('Más','More')}</button><div class="page-head"><div><span class="kick">${t('Ajustes','Settings')}</span><h1>${t('Memoria y respaldo','Memory & backup')}</h1></div></div><div class="setting-grid"><section><h3>${t('Memoria','Memory')}</h3><p><b>${t('Modo local sin conexión activo','Local offline mode active')}</b></p><p>${t('IndexedDB guarda automáticamente en este dispositivo. La edición compartida requiere conectar tu Supabase autoalojado.','IndexedDB autosaves on this device. Shared editing requires connecting your self-hosted Supabase.')}</p></section><section><h3>${t('Moneda','Currency')}</h3><label>USD → MXN<input id="rate" type="number" step=".0001" value="${S.settings.usdToMxn}"></label><small>${esc(S.settings.fxSource)} · ${esc(S.settings.fxDate)}</small><p>${t('Cada precio se guarda en su moneda original; Chispa calcula la otra moneda.','Each price stays in its original currency; Chispa calculates the other currency.')}</p></section><section class="wide"><h3>${t('Respaldo','Backup')}</h3><div class="actions"><button class="secondary" id="json">JSON</button><button class="secondary" id="csv">CSV</button><label class="secondary file">${t('Importar JSON','Import JSON')}<input id="importFile" type="file" hidden></label><button class="secondary" id="print">${t('Imprimir / PDF','Print / PDF')}</button></div></section><section class="wide"><h3>${t('Compartir','Share')}</h3><p>${t('Crea un enlace de solo lectura, un resumen para WhatsApp o usa compartir del teléfono. La edición compartida se activa al conectar Supabase.','Create a read-only link, WhatsApp summary or use the phone share sheet. Shared editing activates when Supabase is connected.')}</p><div class="actions"><button class="secondary" id="share">${I('share')} ${t('Compartir actual','Share current')}</button><button class="secondary" id="wa">WhatsApp</button></div></section><section class="wide"><h3>${t('Restablecer datos locales','Reset local data')}</h3><button class="secondary" id="reset">${t('Restablecer','Reset')}</button></section></div></main>`}
function bottom(){const activeProjectItem=S.view==='item'&&S.items.find(i=>i.id===S.activeItem)?.ct==='project';return `<nav class="bottom">${[['home','home',t('Inicio','Home')],['lists','list',t('Listas','Lists')],['search','search',t('Buscar','Search')],['projects','folder',t('Proyectos','Projects')],['more','more',t('Más','More')]].map(x=>{const on=S.view===x[0]||(x[0]==='projects'&&(S.view==='project'||activeProjectItem))||(x[0]==='lists'&&(S.view==='list'||S.view==='priority'||(S.view==='item'&&!activeProjectItem)));return `<button data-go="${x[0]}" class="${on?'on':''}">${I(x[1])}<span>${x[2]}</span></button>`}).join('')}</nav>`}
function render(){let b=S.shared?shared():S.view==='home'?home():S.view==='priority'?priorityView():S.view==='lists'?lists():S.view==='list'?listView():S.view==='search'?searchView():S.view==='projects'?projects():S.view==='project'?projectView():S.view==='item'?itemView():S.view==='suppliers'?supplierPage():S.view==='settings'?settings():more();$('#app').innerHTML=`<div class="app">${S.shared?'':header()}${b}${S.shared?'':bottom()}</div>`;bind()}
function go(v){S.view=v;save();render();scrollTo({top:0,behavior:'smooth'})}function project(id){S.activeProject=id;S.projectTab='overview';S.view='project';save();render();scrollTo(0,0)}function list(id){S.activeList=id;S.filter='all';S.view='list';save();render();scrollTo(0,0)}function item(id){S.activeItem=id;S.view='item';save();render();scrollTo(0,0)}function toast(m){const d=document.createElement('div');d.className='toast';d.textContent=m;document.body.append(d);setTimeout(()=>d.remove(),1800)}
function sheet(type,ctx={}){const w=document.createElement('div');w.className='sheet-wrap';w.innerHTML=`<button class="shade" aria-label="${t('Cerrar','Close')}"></button><section class="sheet"><i></i>${type==='choice'?choiceForm():type==='list'?listForm(ctx):type==='project'?projectForm(ctx):type==='offer'?offerForm(ctx.id):type==='supplier'?supplierForm(ctx):itemForm(ctx)}</section>`;document.body.append(w);$('.shade',w).onclick=()=>w.remove();bindSheet(w,type,ctx)}
function choiceForm(){return `<h2>${t('Agregar','Add')}</h2><div class="choices"><button data-choice="item">${I('plus')}<span><b>${t('Artículo','Item')}</b><small>${t('Agregar a una lista','Add to a list')}</small></span></button><button data-choice="list">${I('list')}<span><b>${t('Nueva lista','New list')}</b><small>${t('Compras cotidianas o viaje','Everyday shopping or travel')}</small></span></button><button data-choice="project">${I('folder')}<span><b>${t('Nuevo proyecto','New project')}</b><small>${t('Compras con presupuesto y progreso','Shopping with budget and progress')}</small></span></button></div>`}
function itemForm(c={}){const ct=c.ct||'list',cid=c.cid||S.activeList;return `<h2>${t('Agregar artículo','Add item')}</h2><form id="itemForm" class="form"><input type="hidden" name="ct" value="${ct}"><input type="hidden" name="cid" value="${cid}"><label class="wide">${t('Nombre','Name')}<input name="name" required autofocus></label><label>${t('Prioridad','Priority')}<select name="priority"><option value="need">${t('Necesario','Need to have')}</option><option value="nice">${t('Bueno tener','Nice to have')}</option></select></label><label>${t('Cantidad','Quantity')}<input name="qty" value="1"></label><label>${t('Estimación','Planning estimate')}<input name="est" type="number" step=".01"></label><label>${t('Moneda','Currency')}<select name="cur"><option>MXN</option><option>USD</option></select></label><label>${t('Urgencia','Urgency')}<select name="urgency"><option value="today">${t('Hoy','Today')}</option><option value="this-week" selected>${t('Esta semana','This week')}</option><option value="later">${t('Después','Later')}</option></select></label><label>${t('Asignado a','Assigned to')}<select name="assigned"><option value="shared">${t('Compartido','Shared')}</option><option value="me">${t('Yo','Me')}</option><option value="wife">${t('Esposa','Wife')}</option></select></label><label>${t('Tope de presupuesto','Budget cap')}<input name="budgetCap" type="number" step=".01"></label><label>${t('Fecha objetivo','Target date')}<input name="targetDate" type="date"></label><button class="primary wide">${t('Agregar','Add')}</button></form>`}
function listForm(c={}){const l=c.id?S.lists.find(x=>x.id===c.id):null;return `<h2>${l?t('Editar lista','Edit list'):t('Nueva lista','New list')}</h2><form id="listForm" class="form"><input type="hidden" name="id" value="${l?.id||''}"><label class="wide">${t('Nombre','Name')}<input name="name" value="${esc(l?listName(l):'')}" required></label><label class="wide">${t('Categoría','Category')}<select name="cat">${categories.map(c=>`<option value="${c[0]}" ${l?.cat===c[0]?'selected':''}>${t(c[1],c[2])}</option>`).join('')}</select></label><button class="primary wide">${l?t('Guardar cambios','Save changes'):t('Crear lista','Create list')}</button>${l&&l.id!=='quick'?`<button type="button" class="secondary wide danger-link" data-delete-list="${l.id}">${t('Eliminar lista','Delete list')}</button>`:''}</form>`}
function projectForm(c={}){const p=c.id?S.projects.find(x=>x.id===c.id):null;return `<h2>${p?t('Editar proyecto','Edit project'):t('Nuevo proyecto','New project')}</h2><form id="projectForm" class="form"><input type="hidden" name="id" value="${p?.id||''}"><label class="wide">${t('Nombre','Name')}<input name="name" value="${esc(p?projectName(p):'')}" required></label><label class="wide">${t('Descripción','Description')}<textarea name="desc">${esc(p?(S.lang==='es'?p.des:p.den):'')}</textarea></label><button class="primary wide">${p?t('Guardar cambios','Save changes'):t('Crear proyecto','Create project')}</button>${p&&p.id!=='solar'?`<button type="button" class="secondary wide danger-link" data-delete-project="${p.id}">${t('Eliminar proyecto','Delete project')}</button>`:''}</form>`}
function offerForm(id){return `<h2>${t('Guardar oferta','Save offer')}</h2><form id="offerForm" class="form"><input type="hidden" name="id" value="${id}"><label>${t('Fuente','Source')}<select name="source">${markets.slice(0,4).map(x=>`<option>${x[1]}</option>`).join('')}<option>${t('Tienda local','Local store')}</option></select></label><label>${t('Vendedor','Seller')}<input name="seller"></label><label>${t('Precio','Price')}<input name="price" type="number" required step=".01"></label><label>${t('Moneda','Currency')}<select name="cur"><option>MXN</option><option>USD</option></select></label><label>${t('Envío','Shipping')}<input name="shipping" type="number" value="0" step=".01"></label><label>${t('Impuestos','Tax')}<input name="tax" type="number" value="0" step=".01"></label><label>${t('Importación','Import fees')}<input name="import" type="number" value="0" step=".01"></label><label>${t('Descuento','Discount')}<input name="discount" type="number" value="0" step=".01"></label><label>${t('Entrega estimada','Estimated delivery')}<input name="delivery" placeholder="${t('Ej. 3–5 días','e.g. 3–5 days')}"></label><label>${t('Garantía / devolución','Warranty / returns')}<input name="warranty" placeholder="${t('Ej. 30 días / 2 años','e.g. 30 days / 2 years')}"></label><label class="wide">URL<input name="url" type="url"></label><button class="primary wide">${t('Guardar y comparar','Save & compare')}</button></form>`}
function supplierForm(c={}){const s=c.id?S.suppliers.find(x=>x.id===c.id):null;return `<h2>${s?t('Editar proveedor','Edit supplier'):t('Agregar proveedor','Add supplier')}</h2><form id="supplierForm" class="form"><input type="hidden" name="id" value="${s?.id||''}"><label>${t('Nombre','Name')}<input name="name" value="${esc(s?.name||'')}" required></label><label>${t('Tipo','Type')}<select name="type"><option value="local" ${s?.type==='local'?'selected':''}>${t('Local','Local')}</option><option value="online" ${s?.type==='online'?'selected':''}>${t('En línea','Online')}</option></select></label><label>${t('Teléfono','Phone')}<input name="phone" value="${esc(s?.phone||'')}"></label><label>${t('Correo','Email')}<input name="email" type="email" value="${esc(s?.email||'')}"></label><label class="wide">${t('Dirección / ubicación','Address / location')}<input name="place" value="${esc(s?.place||'')}"></label><label class="wide">URL<input name="url" type="url" value="${esc(s?.url||'')}"></label><label class="wide">${t('Nota','Note')}<textarea name="note">${esc(S.lang==='es'?(s?.es||''):(s?.en||''))}</textarea></label><button class="primary wide">${t('Guardar proveedor','Save supplier')}</button></form>`}
function bindSheet(w,type,ctx){$$('[data-choice]',w).forEach(b=>b.onclick=()=>{w.remove();sheet(b.dataset.choice==='item'?'item':b.dataset.choice)});const f=s=>$(s,w);if(f('#itemForm'))f('#itemForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),name=String(d.get('name')).trim(),o=baseItem({ct:d.get('ct'),cid:d.get('cid'),priority:d.get('priority'),es:name,en:name,qty:d.get('qty'),est:Number(d.get('est')||0),cur:d.get('cur'),urgency:d.get('urgency'),assigned:d.get('assigned'),budgetCap:Number(d.get('budgetCap')||0),budgetCur:d.get('cur'),targetDate:d.get('targetDate')});S.items.push(o);save();w.remove();item(o.id)};if(f('#listForm'))f('#listForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),id=String(d.get('id')||''),name=String(d.get('name')).trim();if(id){const l=S.lists.find(x=>x.id===id);l.es=name;l.en=name;l.cat=d.get('cat')}else{const nid='l'+Date.now();S.lists.push({id:nid,es:name,en:name,cat:d.get('cat')});S.activeList=nid}save();w.remove();id?render():list(S.activeList)};if(f('#projectForm'))f('#projectForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),id=String(d.get('id')||''),name=String(d.get('name')).trim(),desc=String(d.get('desc')||'');if(id){const p=S.projects.find(x=>x.id===id);p.es=name;p.en=name;p.des=desc;p.den=desc}else{const nid='p'+Date.now();S.projects.push({id:nid,es:name,en:name,des:desc,den:desc});S.activeProject=nid}save();w.remove();id?render():project(S.activeProject)};if(f('#offerForm'))f('#offerForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),i=S.items.find(x=>x.id===d.get('id'));i.offers=i.offers||[];i.offers.push({id:'o'+Date.now(),source:d.get('source'),seller:d.get('seller'),price:Number(d.get('price')),cur:d.get('cur'),shipping:Number(d.get('shipping')||0),tax:Number(d.get('tax')||0),import:Number(d.get('import')||0),discount:Number(d.get('discount')||0),delivery:String(d.get('delivery')||''),warranty:String(d.get('warranty')||''),url:String(d.get('url')||''),date:new Date().toISOString().slice(0,10)});save();w.remove();render();toast(t('Oferta guardada','Offer saved'))};if(f('#supplierForm'))f('#supplierForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),id=String(d.get('id')||''),note=String(d.get('note')||''),data={id:id||'s'+Date.now(),type:d.get('type'),name:String(d.get('name')),phone:String(d.get('phone')||''),email:String(d.get('email')||''),place:String(d.get('place')||''),url:String(d.get('url')||''),es:note,en:note};if(id)Object.assign(S.suppliers.find(x=>x.id===id),data);else S.suppliers.push(data);save();w.remove();render()};$$('[data-delete-list]',w).forEach(b=>b.onclick=()=>{if(confirm(t('¿Eliminar esta lista y sus artículos?','Delete this list and its items?'))){S.items=S.items.filter(i=>!(i.ct==='list'&&i.cid===b.dataset.deleteList));S.lists=S.lists.filter(l=>l.id!==b.dataset.deleteList);S.activeList='quick';save();w.remove();go('lists')}});$$('[data-delete-project]',w).forEach(b=>b.onclick=()=>{if(confirm(t('¿Eliminar este proyecto y sus artículos?','Delete this project and its items?'))){S.items=S.items.filter(i=>!(i.ct==='project'&&i.cid===b.dataset.deleteProject));S.projects=S.projects.filter(p=>p.id!==b.dataset.deleteProject);S.activeProject='solar';save();w.remove();go('projects')}})}
function bind(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#lang')?.addEventListener('click',()=>{S.lang=S.lang==='es'?'en':'es';save();render()});$('#add')?.addEventListener('click',()=>sheet('choice'));$$('[data-priority-view]').forEach(b=>b.onclick=()=>{S.priorityScope=b.dataset.priorityView;S.view='priority';save();render();scrollTo(0,0)});$$('[data-project]').forEach(b=>b.onclick=()=>project(b.dataset.project));$$('[data-list]').forEach(b=>b.onclick=()=>list(b.dataset.list));$$('[data-item]').forEach(b=>b.onclick=()=>item(b.dataset.item));$$('[data-filter]').forEach(b=>b.onclick=()=>{S.filter=b.dataset.filter;save();render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{S.projectTab=b.dataset.tab;save();render()});$$('[data-jump]').forEach(b=>b.onclick=()=>item(b.dataset.jump));$('[data-start]')?.addEventListener('click',()=>{S.meta.onboarded=true;save();go('lists')});$('[data-new-list]')?.addEventListener('click',()=>sheet('list'));$('[data-new-project]')?.addEventListener('click',()=>sheet('project'));$('[data-new-supplier]')?.addEventListener('click',()=>sheet('supplier'));$$('[data-edit-list]').forEach(b=>b.onclick=e=>{e.stopPropagation();sheet('list',{id:b.dataset.editList})});$$('[data-edit-project]').forEach(b=>b.onclick=e=>{e.stopPropagation();sheet('project',{id:b.dataset.editProject})});$$('[data-edit-supplier]').forEach(b=>b.onclick=()=>sheet('supplier',{id:b.dataset.editSupplier}));$$('[data-del-supplier]').forEach(b=>b.onclick=()=>{if(confirm(t('¿Eliminar proveedor?','Delete supplier?'))){S.suppliers=S.suppliers.filter(s=>s.id!==b.dataset.delSupplier);save();render()}});$$('[data-add-item]').forEach(b=>b.onclick=()=>sheet('item',{ct:b.dataset.ct,cid:b.dataset.cid}));$$('[data-done]').forEach(c=>c.onchange=()=>{const i=S.items.find(x=>x.id===c.dataset.done);i.done=c.checked;save();render()});$$('[data-field]').forEach(e=>{const write=()=>{const i=S.items.find(x=>x.id===e.dataset.id);if(i)i[e.dataset.field]=e.type==='number'?Number(e.value||0):e.value;save()};e.onchange=write;e.onblur=write});$('[data-search-item]')?.addEventListener('click',()=>{const i=S.items.find(x=>x.id===S.activeItem);S.prefill=S.lang==='es'?i.es:i.en;go('search')});$('[data-add-offer]')?.addEventListener('click',()=>sheet('offer',{id:S.activeItem}));$$('[data-del-offer]').forEach(b=>b.onclick=()=>{const i=S.items.find(x=>x.id===S.activeItem);i.offers=i.offers.filter(o=>o.id!==b.dataset.delOffer);save();render()});$('[data-back-item]')?.addEventListener('click',()=>{const i=S.items.find(x=>x.id===S.activeItem);go(i.ct==='project'?'project':'list')});const q=$('#quick'),qb=$('#quickBtn');if(qb)qb.onclick=()=>{const n=q.value.trim();if(!n)return;S.items.push(baseItem({ct:'list',cid:'quick',priority:'need',es:n,en:n,qty:1,cur:'MXN'}));save();render();toast(t('Agregado a Lista rápida','Added to Quick list'))};if(q)q.onkeydown=e=>{if(e.key==='Enter')qb.click()};const sq=$('#q');if(sq&&S.prefill){sq.value=S.prefill;S.prefill=''};$('#searchBtn')?.addEventListener('click',()=>showMarkets(sq.value.trim()));if(sq)sq.onkeydown=e=>{if(e.key==='Enter')$('#searchBtn').click()};const r=$('#rate');if(r)r.onchange=()=>{S.settings.usdToMxn=Number(r.value||FX.rate);S.settings.fxDate=new Date().toISOString().slice(0,10);S.settings.fxSource=t('Tipo manual','Manual rate');save();render()};$('#json')?.addEventListener('click',()=>download('chispa-backup.json',JSON.stringify(S,null,2),'application/json'));$('#csv')?.addEventListener('click',exportCsv);$('#importFile')?.addEventListener('change',importJson);$('#print')?.addEventListener('click',()=>print());$('#reset')?.addEventListener('click',reset);$('#share')?.addEventListener('click',shareCurrent);$('#wa')?.addEventListener('click',whatsapp)}
function showMarkets(q){if(!q)return toast(t('Escribe lo que buscas','Type what you are looking for'));$('#marketLinks').innerHTML=markets.map(m=>`<a href="${searchUrl(m[0],q)}" target="_blank" rel="noopener"><strong>${m[1]}</strong><small>${esc(q)}</small><b>${t('Abrir búsqueda','Open search')} ↗</b></a>`).join('')}
function current(){if(S.view==='project'||S.items.find(i=>i.id===S.activeItem)?.ct==='project'){const p=S.projects.find(x=>x.id===S.activeProject);return{title:projectName(p),a:items('project',p.id)}}const l=S.lists.find(x=>x.id===S.activeList)||S.lists[0];return{title:listName(l),a:items('list',l.id)}}function payload(){const c=current();return{title:c.title,items:c.a.map(i=>({n:S.lang==='es'?i.es:i.en,p:i.priority,d:!!i.done}))}}function enc(o){return btoa(unescape(encodeURIComponent(JSON.stringify(o)))).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}function dec(s){try{let p=s.replaceAll('-','+').replaceAll('_','/');while(p.length%4)p+='=';return JSON.parse(decodeURIComponent(escape(atob(p))))}catch{return null}}async function shareCurrent(){const p=payload(),url=location.origin+location.pathname+'#share='+enc(p),d={title:'Chispa — '+p.title,text:t('Lista de solo lectura','Read-only list'),url};try{if(navigator.share)await navigator.share(d);else{await navigator.clipboard.writeText(url);toast(t('Enlace copiado','Link copied'))}}catch{}}function whatsapp(){const p=payload(),x=encodeURIComponent(`Chispa — ${p.title}\n\n`+p.items.map(i=>`${i.d?'✓':'□'} ${i.n}`).join('\n'));open(`https://wa.me/?text=${x}`,'_blank','noopener')}function sharedHash(){if(location.hash.startsWith('#share=')){const d=dec(location.hash.slice(7));if(d)S.shared=d}}function shared(){return `<main class="page"><div class="share-head"><span>${t('Solo lectura','Read only')}</span><h1>${esc(S.shared.title)}</h1></div><div class="item-list">${S.shared.items.map(i=>`<div class="item static"><span class="box ${i.d?'done':''}">${i.d?I('check'):''}</span><span><strong>${esc(i.n)}</strong><small>${i.p==='need'?t('Necesario','Need to have'):t('Bueno tener','Nice to have')}</small></span></div>`).join('')}</div></main>`}
function download(n,x,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([x],{type}));a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function exportCsv(){const rows=[['id','type','container','priority','name_es','name_en','done','status','urgency','assigned','budget_cap','budget_currency','target_date','paid','currency','seller'],...S.items.map(i=>[i.id,i.ct,i.cid,i.priority,i.es,i.en,i.done,i.status,i.urgency,i.assigned,i.budgetCap,i.budgetCur,i.targetDate,i.paid,i.paidCur,i.seller])];download('chispa.csv',rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv')}function importJson(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{migrate(JSON.parse(r.result));save();render();toast(t('Respaldo importado','Backup imported'))}catch{toast(t('Archivo inválido','Invalid file'))}};r.readAsText(f)}function reset(){if(confirm(t('¿Borrar los cambios locales y volver al inicio?','Erase local changes and return to starter data?'))){S={v:3,lang:'es',view:'home',activeList:'quick',activeProject:'solar',projectTab:'overview',activeItem:null,filter:'all',priorityScope:'need',lists:[],projects:[],items:[],suppliers:[],settings:{usdToMxn:FX.rate,fxDate:FX.date,fxSource:FX.source,sync:'local'},meta:{onboarded:false,updatedAt:null}};seed();save();render()}}
window.addEventListener('hashchange',()=>{S.shared=null;sharedHash();render()});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));load();